-- ACTIVE counts: Richmond 6, Tucson 5, San Antonio 6 — at or above the
-- docs/CITY_PAGE_POLICY.md §11 minimum (>=5). Memphis (3), New Orleans (4),
-- Birmingham (2), Jacksonville (2) and Louisville (2) stay unpublished.
UPDATE "City" SET "published" = 1 WHERE "slug" IN ('richmond', 'tucson', 'san-antonio');
UPDATE "City" SET "intro" = 'Richmond''s listings come from two organizers. MahjongRVA teaches American Mahjong with beginner classes and events, and The Lucky Sparrow hosts NMJL-based socials and open play at local venues such as a brewery, a bar and the Poe Museum. Events move between venues and often carry a ticket price, so confirm the location and cost before you go. If you are new, a MahjongRVA basic class is a good first step.' WHERE "slug" = 'richmond';
UPDATE "City" SET "intro" = 'Tucson''s American Mahjong centers on Tucson J, the Jewish community center, which offers a free Tuesday open play and multi-session classes using official National Mah Jongg League rules. The Intro to Mahj class starts new groups through the fall, and a Next Level class follows for returning players. If you are new, start with the intro class, then join Tuesday open play. Check the Tucson J program page for current session dates.' WHERE "slug" = 'tucson';
UPDATE "City" SET "intro" = 'San Antonio has a dedicated parlor and a public-library option. The Polished Tile offers Mahjong 101, 102 and 103 lessons, guided play and open play, using the National Mah Jongg League card. Encino Library hosts a free open play on Tuesday afternoons. New players can start with Mahjong 101 at The Polished Tile, then join open play at the library. Check the calendars for current times.' WHERE "slug" = 'san-antonio';
